local RunService = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Mutations = require(ReplicatedStorage.Shared.Modules.Data.Mutations)
local Rarities = require(ReplicatedStorage.Shared.Modules.Data.Rarity)
local Configuration = require(ReplicatedStorage.Shared.Configuration)



local TEMPLATE_PLATFORMS = {{
	Unlocked = true;
	NPC = nil;
	NPCMultiplier = nil;
	NPCMutation = nil;
	Money = 0;
	OfflineMoney = 0;
}}
for i = 2, Configuration.PlatformCount do
	TEMPLATE_PLATFORMS[i] = {
		Unlocked = false;
		NPC = nil;
		NPCMultiplier = nil;
		NPCMutation = nil;
		Money = 0;
		OfflineMoney = 0;
	}
end
local autoSellTemplate = {}
for name in Mutations do
	autoSellTemplate[name] = false
end
for name in Rarities do
	autoSellTemplate[name] = false
end

local DATA_TEMPLATE = {
	Money = 200;
	ExitTimestamp = 0;
	LanesUnlocked = 1;
	EnemiesSpawned = 0;
	Tutorial = 0;
	Rebirths = 0;

	PlayerStats = {
		TimePlayed = 0;
		TotalPlantsPlaced = 0;
	};
	Platforms = TEMPLATE_PLATFORMS;
	Lanes = {false, false, false, true, false, false, false};
	Index = {};
	OwnedProducts = {};
	AutoSell = autoSellTemplate;
	Plants = {};
	Inventory = {};
	SeedShopInfo = {
		LastRestock = 0,
		StockInfo = {},
	};
	--GearShopInfo = {
	--	LastRestock = 0,
	--	StockInfo = {},
	--};
};


for mutationName, mutationInfo in pairs(Mutations) do
	DATA_TEMPLATE.Index[mutationName] = {}
end


do -- DEBUGGING DATA
	if not RunService:IsStudio() then
		return DATA_TEMPLATE
	end

	--DATA_TEMPLATE.Cash = 12788271
end

return DATA_TEMPLATE

