local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Signal = require(ReplicatedStorage.Packages.Zone.Signal)

return {

	-- Signal fired when a player data loads
	PLAYER_DATA_LOADED = Signal.new();

	-- Signal fired when a plot is assigned an owner, after the Base state object is created.
	PLOT_ASSIGNED = Signal.new();

}

return {
